"def build_graph(entities, assertions):
    valid_relations = {
        "made_of": ("Part", "Material"),
        "verified_by": ("Part", "Analysis"),
        "satisfies": ("Analysis", "Requirement"),
    }

    entity_types = {}
    for entity in entities or []:
        entity_id = entity.get("id")
        if isinstance(entity_id, str) and entity_id:
            entity_types[entity_id] = entity.get("type")

    edge_evidence = {}
    issues = []

    for assertion in assertions or []:
        if not isinstance(assertion, dict):
            source_id = None
        else:
            source_id = assertion.get("source_id")

        if not isinstance(source_id, str) or source_id == "":
            issues.append({"source_id": "", "reason": "missing_source"})
            continue

        relation = assertion.get("relation")
        if relation not in valid_relations:
            issues.append({"source_id": source_id, "reason": "unknown_relation"})
            continue

        subject = assertion.get("subject")
        obj = assertion.get("object")

        if (
            not isinstance(subject, str)
            or subject not in entity_types
            or not isinstance(obj, str)
            or obj not in entity_types
        ):
            issues.append({"source_id": source_id, "reason": "missing_entity"})
            continue

        expected_types = valid_relations[relation]
        actual_types = (entity_types[subject], entity_types[obj])
        if actual_types != expected_types:
            issues.append({"source_id": source_id, "reason": "type_mismatch"})
            continue

        key = (subject, relation, obj)
        edge_evidence.setdefault(key, []).append(source_id)

    edges = []
    for key in sorted(edge_evidence):
        subject, relation, obj = key
        edges.append({
            "subject": subject,
            "relation": relation,
            "object": obj,
            "evidence": sorted(set(edge_evidence[key])),
        })

    issues.sort(key=lambda issue: (issue["source_id"], issue["reason"]))

    return {"edges": edges, "issues": issues}"
